#!/usr/bin/env node
// Generates src/catalog.generated.mjs from the transition-preset catalog (<skill>/schemas/transition-presets.json), the one source
// of truth the engine and the kit share. The kit never hand-copies a preset: validation, the type table and the renderers read the
// generated module.
//
//   node tools/sync-catalog.mjs                      regenerate src/catalog.generated.mjs
//   node tools/sync-catalog.mjs --check              exit 1 when the generated file differs from the catalog (drift); writes nothing
//   node tools/sync-catalog.mjs --catalog FILE       read another catalog file (tests)
//   node tools/sync-catalog.mjs --out FILE           write somewhere else (tests); --check compares against FILE
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const KIT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const arg = (name) => {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
};
const catalogFile = path.resolve(arg('--catalog') || path.join(KIT, '..', 'schemas', 'transition-presets.json'));
const outFile = path.resolve(arg('--out') || path.join(KIT, 'src', 'catalog.generated.mjs'));
const SCHEMA = 'jjv/transition-presets/v1';

// Display text (labels, when-to-use, notes) belongs to the gallery and the CLI, which read the catalog JSON directly. The kit needs the
// RULES only, and carries no wording of any episode: these keys are left out of the generated module.
export const DISPLAY_KEYS = ['label', 'when', 'kids_note'];
const rules = (preset) => Object.fromEntries(Object.entries(preset).filter(([key]) => !DISPLAY_KEYS.includes(key)));

function generate() {
  const bytes = fs.readFileSync(catalogFile);
  const catalog = JSON.parse(bytes.toString('utf8').replace(/^﻿/u, ''));
  if (catalog.schema !== SCHEMA) throw new Error(`${catalogFile}: schema must be ${SCHEMA}, got ${catalog.schema}`);
  if (!catalog.presets || typeof catalog.presets !== 'object') throw new Error(`${catalogFile}: presets missing`);
  const sha = crypto.createHash('sha256').update(bytes).digest('hex');
  // one preset per line keeps a catalog change readable in the diff
  const lines = Object.entries(catalog.presets).map(([name, preset]) => `  ${JSON.stringify(name)}: ${JSON.stringify(rules(preset))},`);
  const rest = Object.fromEntries(Object.entries(catalog).filter(([key]) => key !== 'presets'));
  return [
    '// GENERATED by tools/sync-catalog.mjs from <skill>/schemas/transition-presets.json. DO NOT EDIT: change the catalog and regenerate',
    '// (node tools/sync-catalog.mjs). `node tools/sync-catalog.mjs --check` (run by npm test) fails when this file has drifted.',
    `export const CATALOG_SOURCE_SHA256 = ${JSON.stringify(sha)};`,
    `const meta = ${JSON.stringify(rest)};`,
    'const presets = {',
    ...lines,
    '};',
    'const freeze = (v) => (v && typeof v === "object" ? Object.freeze(Object.values(v).forEach(freeze) || v) : v);',
    'export const CATALOG = freeze({...meta, presets});',
    '',
  ].join('\n');
}

try {
  const text = generate();
  if (process.argv.includes('--check')) {
    const have = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : null;
    if (have !== text) {
      process.stderr.write(`catalog drift: ${outFile} does not match ${catalogFile}${have === null ? ' (file is missing)' : ''}.\n` +
        'Regenerate it: node remotion-kit/tools/sync-catalog.mjs (and commit the result).\n');
      process.exit(1);
    }
    process.stdout.write(`catalog in sync (${Object.keys(JSON.parse(fs.readFileSync(catalogFile, 'utf8')).presets).length} presets)\n`);
  } else {
    fs.writeFileSync(outFile, text);
    process.stdout.write(`wrote ${outFile}\n`);
  }
} catch (error) {
  process.stderr.write(`sync-catalog: ${error.message}\n`);
  process.exit(2);
}
